{"teaching_intent":"让学生通过调节抛出角度与初速度，观察斜抛运动中不可见的过程：竖直分速度在最高点归零并反向、水平分速度恒定、重力加速度始终竖直向下，以及动能与势能此消彼长而机械能守恒；通过慢放、暂停与拖动时间轴，验证最高点时刻、射程与速度方向之间的因果关系，首屏保持暂停在物理时间 0，由老师点击播放掌控讲解节奏。","html":"<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>抛体运动纯物理模型</title>
<!--HARNESS_PRIMITIVES-->
<!--HARNESS_MODEL-->
<!--HARNESS_INPUT-->
<style>
*{box-sizing:border-box;margin:0;padding:0}
body{background:#0e1420;color:#e8eef7;font-family:"PingFang SC","Microsoft YaHei",sans-serif;line-height:1.5}
header{padding:14px 18px;border-bottom:1px solid #22304a}
header h1{font-size:20px}
header p{font-size:13px;color:#9fb2cc;margin-top:4px}
main{display:flex;flex-wrap:wrap;gap:14px;padding:14px}
.stage{flex:1 1 480px;min-width:300px;background:#131c2e;border:1px solid #22304a;border-radius:12px;padding:8px}
svg{width:100%;height:auto;display:block}
.panel{flex:1 1 300px;max-width:420px;display:flex;flex-direction:column;gap:12px}
.card{background:#131c2e;border:1px solid #22304a;border-radius:12px;padding:12px 14px}
.card h2{font-size:15px;margin-bottom:8px;color:#9fd0ff}
.ctl{margin:10px 0}
.ctl label{display:flex;justify-content:space-between;font-size:14px;margin-bottom:4px}
.ctl label b{color:#ffd24a}
input[type=range]{width:100%;height:44px;accent-color:#4aa8ff;cursor:pointer}
.row{display:flex;flex-wrap:wrap;gap:8px;align-items:center}
button{min-height:44px;min-width:64px;padding:0 14px;border-radius:10px;border:1px solid #33507e;background:#1b2a44;color:#e8eef7;font-size:15px;cursor:pointer}
button:active{background:#27406a}
button.on{background:#2f6fd0;border-color:#6aa8ff}
.timer{font-size:14px;display:flex;flex-wrap:wrap;gap:6px 16px}
.timer span b{color:#7ef0b2}
#st{color:#ffb86b;font-weight:700}
.rd{font-size:13px;color:#cfe0f5;background:#0d1524;border-radius:8px;padding:8px 10px;min-height:44px}
.bars{margin-top:6px}
.bar{height:14px;border-radius:7px;background:#0d1524;overflow:hidden;margin:5px 0;position:relative}
.bar i{display:block;height:100%;border-radius:7px}
.bar em{position:absolute;left:8px;top:0;font-size:11px;font-style:normal;line-height:14px;color:#fff;text-shadow:0 0 3px #000}
.ev{font-size:13px;color:#9fb2cc}
@media(max-width:720px){.panel{max-width:none}header h1{font-size:17px}}
</style>
</head>
<body>
<header>
<h1>抛体运动纯物理模型</h1>
<p>调节抛出角度与初速度，观察最高点、射程、速度方向与能量转化。页面加载后暂停在物理时间 0，请点击播放开始演示。</p>
</header>
<main>
<section class="stage">
<svg id="sv" viewBox="0 0 800 430" aria-label="抛体运动轨迹视图">
<rect x="0" y="0" width="800" height="430" fill="#131c2e"/>
<line x1="0" y1="378" x2="800" y2="378" stroke="#6f8f6a" stroke-width="3"/>
<path id="traj" fill="none" stroke="#5f7ea8" stroke-width="2" stroke-dasharray="6 5"/>
<polyline id="trail" fill="none" stroke="#41e29a" stroke-width="3"/>
<line id="hline" stroke="#ffaa55" stroke-width="1.5" stroke-dasharray="4 4"/>
<circle id="apex" r="6" fill="#ffaa55" stroke="#fff" stroke-width="1.5"/>
<text id="apexTx" fill="#ffaa55" font-size="13">最高点 vy=0</text>
<line id="rngLn" stroke="#6aa8ff" stroke-width="2"/>
<circle id="land" r="5" fill="#6aa8ff"/>
<text id="rngTx" fill="#6aa8ff" font-size="13"></text>
<circle id="launch" r="5" fill="#ffffff"/>
<text id="launchTx" fill="#cfe0f5" font-size="12">抛出点</text>
<g id="garr">
<line x1="0" y1="0" x2="0" y2="24" stroke="#ff6666" stroke-width="3"/>
<polygon points="0,34 -6,22 6,22" fill="#ff6666"/>
<text x="9" y="30" fill="#ff6666" font-size="12">g</text>
</g>
<g id="varr">
<line id="vln" stroke="#ffd24a" stroke-width="3"/>
<polygon id="vhd" fill="#ffd24a"/>
<text id="vtx" fill="#ffd24a" font-size="12">v</text>
</g>
<circle id="ball" r="10" fill="#4aa8ff" stroke="#ffffff" stroke-width="2"/>
</svg>
</section>
<aside class="panel">
<div class="card">
<h2>可调参数</h2>
<div class="ctl">
<label>抛出仰角 <b><span id="angV"></span>°</b></label>
<input type="range" id="ang" data-control min="15" max="80" step="1">
</div>
<div class="ctl">
<label>初速度 <b><span id="spdV"></span> m/s</b></label>
<input type="range" id="spd" data-control min="5" max="35" step="0.5">
</div>
<div class="ev" id="fix"></div>
</div>
<div class="card">
<h2>时间与播放</h2>
<div class="timer">
<span>物理时间 <b data-physical-time>—</b></span>
<span>演示倍率 <b data-demo-time>—</b></span>
<span id="st">已暂停</span>
</div>
<input type="range" id="seek" min="0" max="1000" value="0" aria-label="拖动时间轴">
<div class="row">
<button id="pp">▶ 播放</button>
<button data-replay>↺ 回放</button>
<button class="rate" data-r="0.25">0.25×</button>
<button class="rate" data-r="0.5">0.5×</button>
<button class="rate on" data-r="1">1×</button>
<button class="rate" data-r="2">2×</button>
</div>
</div>
<div class="card">
<h2>状态读数</h2>
<div class="rd" data-readout>—</div>
<div class="bars">
<div class="bar"><i id="ke" style="background:#ffb84a;width:50%"></i><em>动能</em></div>
<div class="bar"><i id="pe" style="background:#4ad0ff;width:50%"></i><em>势能</em></div>
</div>
<div class="rd" id="en" style="margin-top:6px">—</div>
<div class="ev" id="evTx" style="margin-top:8px">—</div>
</div>
</aside>
</main>
<script>
const HI = globalThis.__HARNESS_INPUT__;
const scen = Object.assign({}, HI.scenario);
const $ = id => document.getElementById(id);
const ang = $('ang'), spd = $('spd'), seek = $('seek'), pp = $('pp');
ang.value = scen.angle_deg;
spd.value = scen.speed_m_s;
$('angV').textContent = scen.angle_deg;
$('spdV').textContent = scen.speed_m_s;
$('fix').textContent = '固定条件：质量 ' + scen.mass_kg + ' kg · g = ' + scen.g_m_s2 + ' m/s² · 抛出点 (' + scen.x0_m + ', ' + scen.y0_m + ') m · 模式 ' + scen.mode;
const GROUND = 378;
let data = null, dur = 1, tl = null, scale = 20, playing = false, x0 = 0, y0 = 0;
const X = x => 40 + x * scale;
const Y = y => GROUND - y * scale;
const f1 = v => (Math.round(v * 10) / 10).toFixed(1);
function axis(T, n){ const a = []; for(let i = 0; i <= n; i++) a.push(T * i / n); return a; }
function stateAt(t){
  const s = data.states;
  if(t <= 0) return s[0];
  const last = s[s.length - 1];
  if(t >= last.t_s) return last;
  let lo = 0, hi = s.length - 1;
  while(hi - lo > 1){ const m = (lo + hi) >> 1; if(s[m].t_s <= t) lo = m; else hi = m; }
  const a = s[lo], b = s[hi], k = (t - a.t_s) / ((b.t_s - a.t_s) || 1), r = {};
  for(const key in a){ if(typeof a[key] === 'number') r[key] = a[key] + (b[key] - a[key]) * k; }
  return r;
}
function buildStatics(){
  const ev = data.events, ss = data.states;
  x0 = ss[0].x_m; y0 = ss[0].y_m;
  scale = Math.min(720 / Math.max(ev.range_m * 1.08 + x0, 2), 316 / Math.max(ev.max_height_m * 1.18, 1));
  const pts = ss.map(p => X(p.x_m).toFixed(1) + ' ' + Y(p.y_m).toFixed(1));
  $('traj').setAttribute('d', 'M' + pts.join(' L'));
  const ap = stateAt(ev.apex_time_s);
  $('apex').setAttribute('cx', X(ap.x_m)); $('apex').setAttribute('cy', Y(ap.y_m));
  $('apexTx').setAttribute('x', Math.min(X(ap.x_m) + 10, 640)); $('apexTx').setAttribute('y', Y(ap.y_m) - 10);
  $('hline').setAttribute('x1', X(x0)); $('hline').setAttribute('x2', X(ap.x_m));
  $('hline').setAttribute('y1', Y(ap.y_m)); $('hline').setAttribute('y2', Y(ap.y_m));
  const lx = X(x0 + ev.range_m);
  $('rngLn').setAttribute('x1', X(x0)); $('rngLn').setAttribute('x2', lx);
  $('rngLn').setAttribute('y1', GROUND + 20); $('rngLn').setAttribute('y2', GROUND + 20);
  $('land').setAttribute('cx', lx); $('land').setAttribute('cy', GROUND);
  $('rngTx').setAttribute('x', Math.max(30, (X(x0) + lx) / 2 - 40)); $('rngTx').setAttribute('y', GROUND + 40);
  $('rngTx').textContent = '射程 ' + f1(ev.range_m) + ' m';
  $('launch').setAttribute('cx', X(x0)); $('launch').setAttribute('cy', Y(y0));
  $('launchTx').setAttribute('x', X(x0) + 8); $('launchTx').setAttribute('y', Y(y0) - 8);
  $('evTx').textContent = '全程飞行 ' + ev.flight_time_s.toFixed(2) + ' s · 最高点 ' + f1(ev.max_height_m) + ' m（t=' + ev.apex_time_s.toFixed(2) + ' s）· 射程 ' + f1(ev.range_m) + ' m · 等高最优角 ' + f1(ev.optimal_equal_height_angle_deg) + '°';
}
function resample(){
  const probe = coursewareModel.sample({scenario: scen, times_s: axis(15, 300)});
  const T = Math.max(0.05, probe.events.flight_time_s);
  data = coursewareModel.sample({scenario: scen, times_s: axis(T, Math.max(160, Math.ceil(T * 90)))});
  dur = T;
  buildStatics();
  if(tl) tl.pause();
  playing = false;
  tl = CoursewarePrimitives.createTimeline({durationPhysicalS: dur, onChange: update});
  tl.seek(0);
  seek.value = 0;
  update({physicalTimeS: 0, demoRate: 1, playing: false});
}
function update(state){
  const t = Math.min(state.physicalTimeS, dur), st = stateAt(t);
  const bx = X(st.x_m), by = Y(st.y_m);
  $('ball').setAttribute('cx', bx); $('ball').setAttribute('cy', by);
  let tr = '';
  const ss = data.states;
  for(let i = 0; i < ss.length && ss[i].t_s <= t; i++) tr += X(ss[i].x_m).toFixed(1) + ',' + Y(ss[i].y_m).toFixed(1) + ' ';
  tr += bx.toFixed(1) + ',' + by.toFixed(1);
  $('trail').setAttribute('points', tr);
  const k = scale * 0.32;
  const ex = bx + st.vx_m_s * k, ey = by - st.vy_m_s * k;
  if(Math.hypot(ex - bx, ey - by) > 4){
    $('varr').style.display = '';
    $('vln').setAttribute('x1', bx); $('vln').setAttribute('y1', by);
    $('vln').setAttribute('x2', ex); $('vln').setAttribute('y2', ey);
    const a2 = Math.atan2(ey - by, ex - bx), s1 = a2 + 2.62, s2 = a2 - 2.62;
    $('vhd').setAttribute('points', ex.toFixed(1) + ',' + ey.toFixed(1) + ' ' + (ex + 11 * Math.cos(s1)).toFixed(1) + ',' + (ey + 11 * Math.sin(s1)).toFixed(1) + ' ' + (ex + 11 * Math.cos(s2)).toFixed(1) + ',' + (ey + 11 * Math.sin(s2)).toFixed(1));
    $('vtx').setAttribute('x', ex + 8); $('vtx').setAttribute('y', ey - 6);
  } else { $('varr').style.display = 'none'; }
  $('garr').setAttribute('transform', 'translate(' + bx.toFixed(1) + ' ' + by.toFixed(1) + ')');
  document.querySelector('[data-physical-time]').textContent = CoursewarePrimitives.formatPhysicalTime(state.physicalTimeS);
  document.querySelector('[data-demo-time]').textContent = CoursewarePrimitives.formatDemoRate(state.demoRate);
  const sp = Math.hypot(st.vx_m_s, st.vy_m_s);
  document.querySelector('[data-readout]').textContent = '位置 (' + f1(st.x_m) + ', ' + f1(st.y_m) + ') m · vx ' + f1(st.vx_m_s) + ' m/s（恒定）· vy ' + f1(st.vy_m_s) + ' m/s · 速率 ' + f1(sp) + ' m/s · 加速度 (' + f1(st.ax_m_s2) + ', ' + f1(st.ay_m_s2) + ') m/s²';
  const me = st.mechanical_j || 1;
  $('ke').style.width = Math.max(2, st.kinetic_j / me * 100) + '%';
  $('pe').style.width = Math.max(2, st.potential_j / me * 100) + '%';
  $('en').textContent = '动能 ' + st.kinetic_j.toFixed(1) + ' J · 势能 ' + st.potential_j.toFixed(1) + ' J · 机械能 ' + st.mechanical_j.toFixed(1) + ' J（守恒）';
  playing = !!state.playing;
  $('st').textContent = playing ? '▶ 播放中' : '⏸ 已暂停';
  pp.textContent = playing ? '⏸ 暂停' : '▶ 播放';
  if(document.activeElement !== seek) seek.value = Math.round(t / dur * 1000);
}
pp.addEventListener('click', () => { if(!tl) return; if(playing) tl.pause(); else tl.play(); });
document.querySelector('[data-replay]').addEventListener('click', () => { if(tl) tl.replay(); });
seek.addEventListener('input', () => { if(!tl) return; tl.pause(); tl.seek(seek.value / 1000 * dur); });
document.querySelectorAll('.rate').forEach(b => b.addEventListener('click', () => {
  if(!tl) return;
  tl.setDemoRate(parseFloat(b.dataset.r));
  document.querySelectorAll('.rate').forEach(o => o.classList.toggle('on', o === b));
}));
function onCtl(){
  scen.angle_deg = parseFloat(ang.value);
  scen.speed_m_s = parseFloat(spd.value);
  $('angV').textContent = ang.value;
  $('spdV').textContent = spd.value;
  resample();
}
ang.addEventListener('change', onCtl);
spd.addEventListener('change', onCtl);
document.addEventListener('visibilitychange', () => { if(document.hidden && tl) tl.pause(); });
resample();
</script>
</body>
</html>"}
